import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build and locally improve a minimum union-cost directed broadcast topology."""
    topology = BroadCastTopology(src, dsts, num_partitions)

    # Costless/missing-cost edges must not accidentally receive NetworkX's
    # default unit weight.  Source incoming edges and loops cannot help a
    # source-rooted broadcast.
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    bad_edges = []
    for u, v, data in h.edges(data=True):
        cost = data.get("cost")
        try:
            if cost is None or float(cost) < 0:
                bad_edges.append((u, v))
        except (TypeError, ValueError):
            bad_edges.append((u, v))
    h.remove_edges_from(bad_edges)

    # BroadCastTopology is keyed by destination, so duplicate names cannot
    # represent distinct output obligations.
    unique_dsts = list(dict.fromkeys(dsts))
    if not unique_dsts:
        return topology

    def base_distance(dst):
        try:
            return nx.dijkstra_path_length(h, src, dst, weight="cost")
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            return float("inf")

    distances = {dst: base_distance(dst) for dst in unique_dsts}
    reachable = [dst for dst in unique_dsts if distances[dst] != float("inf")]

    # Preserve the parent behavior for ordinary reachable instances.  Empty
    # paths are valid for src itself; unreachable destinations retain None.
    if not reachable:
        return topology

    # Generate a bounded pool containing both ordinary and marginal-cost routes.
    # The global selection below can therefore trade a slightly longer route for
    # substantially greater reuse of a common broadcast trunk.
    ascending = sorted(reachable, key=lambda d: (distances[d], str(d)))
    marginal_counts = {}
    candidates = {}

    def marginal(u, v, data):
        return 0.0 if marginal_counts.get((u, v), 0) else float(data["cost"])

    for dst in ascending:
        pool = []
        try:
            p = nx.dijkstra_path(h, src, dst, weight="cost")
            pool.append(p)
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass
        try:
            p = nx.dijkstra_path(h, src, dst, weight=marginal)
            pool.append(p)
            for edge in zip(p, p[1:]):
                marginal_counts[edge] = marginal_counts.get(edge, 0) + 1
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass
        try:
            generator = nx.shortest_simple_paths(h, src, dst, weight="cost")
            for p in generator:
                if p not in pool:
                    pool.append(p)
                if len(pool) >= 8:
                    break
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass
        candidates[dst] = [
            list(zip(p, p[1:])) for p in pool
            if p and p[0] == src and p[-1] == dst
        ]

    selected = {}
    try:
        import numpy as np
        from scipy.optimize import Bounds, LinearConstraint, milp
        from scipy.sparse import lil_matrix

        edge_set = sorted(
            {edge for paths in candidates.values() for path in paths for edge in path},
            key=str,
        )
        edge_index = {edge: i for i, edge in enumerate(edge_set)}
        y_index = {}
        n = len(edge_set)
        for dst in reachable:
            for j in range(len(candidates.get(dst, []))):
                y_index[(dst, j)] = n
                n += 1

        objective = np.zeros(n)
        objective[:len(edge_set)] = [
            float(h[u][v]["cost"]) for u, v in edge_set
        ]
        rows = []
        lower = []
        upper = []

        # Exactly one candidate route is selected for every reachable destination.
        for dst in reachable:
            row = {}
            for j in range(len(candidates.get(dst, []))):
                row[y_index[(dst, j)]] = 1.0
            if row:
                rows.append(row)
                lower.append(1.0)
                upper.append(1.0)

        # A selected route activates every edge it traverses.
        for (dst, j), yi in y_index.items():
            for edge in candidates[dst][j]:
                row = {yi: 1.0, edge_index[edge]: -1.0}
                rows.append(row)
                lower.append(-np.inf)
                upper.append(0.0)

        matrix = lil_matrix((len(rows), n), dtype=float)
        for i, row in enumerate(rows):
            for j, value in row.items():
                matrix[i, j] = value
        result = milp(
            objective,
            integrality=np.ones(n),
            bounds=Bounds(np.zeros(n), np.ones(n)),
            constraints=LinearConstraint(matrix.tocsr(), lower, upper),
            options={"time_limit": 2.0},
        )
        if result.success and result.x is not None:
            for dst in reachable:
                for j in range(len(candidates.get(dst, []))):
                    if result.x[y_index[(dst, j)]] > 0.5:
                        selected[dst] = candidates[dst][j]
                        break
    except (ImportError, ValueError, TypeError, AttributeError, RuntimeError):
        selected = {}

    # Valid incumbent fallback if the bounded optimizer or candidate pool fails.
    if len(selected) != len(reachable):
        selected = {}
        counts = {}
        for dst in ascending:
            def fallback_weight(u, v, data):
                return 0.0 if counts.get((u, v), 0) else float(data["cost"])
            try:
                path = nx.dijkstra_path(h, src, dst, weight=fallback_weight)
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                continue
            selected[dst] = list(zip(path, path[1:]))
            for edge in selected[dst]:
                counts[edge] = counts.get(edge, 0) + 1

    for dst in unique_dsts:
        edge_pairs = selected.get(dst)
        if edge_pairs is None:
            continue
        edges = [[u, v, G[u][v]] for u, v in edge_pairs]
        for partition in range(topology.num_partitions):
            topology.set_dst_partition_paths(dst, partition, list(edges))

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(
            os.path.join(current_dir, "profiles/throughput.csv")
        )
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = []
    for edge in G.edges.data():
        edge_src, edge_dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((edge_src, edge_dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    return BroadCastTopology(src, dsts, num_partitions)


def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    return search_algorithm(src, dsts, G, num_partitions)

